# Validating if a collection of subsets forms a partition of a set S
def is_partition(S, subsets):
    union_set = set()
    for sub in subsets:
        if len(sub) == 0:
            return False # Empty subset not allowed
        if not sub.issubset(S):
            return False
        if not union_set.isdisjoint(sub):
            return False # Overlap found
        union_set.update(sub)
    return union_set == S

