# Python 3.13+: Generating covering relations for a Hasse Diagram from a POSET

def get_covering_relations(elements, relations):
    # Remove reflexive pairs
    strict_rel = {(x, y) for x, y in relations if x != y}

    coverings = set()
    for x, y in strict_rel:
        is_covered = True
        for z in elements:
            # Check if there is an intermediate element z such that x < z < y
            if (x, z) in strict_rel and (z, y) in strict_rel:
                is_covered = False
                break
        if is_covered:
            coverings.add((x, y))

    return coverings

