def count_components(V, edges):
    adj = {v: [] for v in V}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = set()
    def dfs(u):
        visited.add(u)
        for nb in adj[u]:
            if nb not in visited:
                dfs(nb)
    comp = 0
    for v in V:
        if v not in visited:
            dfs(v)
            comp += 1
    return comp
# Example usage
V = {1,2,3,4,5}
edges = {(1,2),(2,3),(4,5)}
print(count_components(V, edges))  # Output: 2

def is_tree(V, edges):
    if len(edges) != len(V) - 1:
        return False
    # Ensure connectivity
    return count_components(V, edges) == 1
# Using previous count_components function
