# Verifying ring axioms using a custom algebraic structure class in Python 3.13+
class RingZ4:
    # Integers modulo 4: Z_4 = {0, 1, 2, 3}
    def __init__(self, val):
        self.val = val % 4

    def __add__(self, other):
        return RingZ4((self.val + other.val) % 4)

    def __mul__(self, other):
        return RingZ4((self.val * other.val) % 4)

    def __repr__(self):
        return f"RingZ4({self.val})"

