def is_commutative(elements, mult_func):
    for x in elements:
        for y in elements:
            if mult_func(x, y) != mult_func(y, x):
                return False
    return True

def check_distributive(elements, add_func, mult_func):
    for a in elements:
        for b in elements:
            for c in elements:
                lhs = mult_func(a, add_func(b, c))
                rhs = add_func(mult_func(a, b), mult_func(a, c))
                if lhs != rhs:
                    return False
    return True

def find_zero_divisors(n):
    divisors = set()
    for i in range(1, n):
        for j in range(1, n):
            if (i * j) % n == 0:
                divisors.add(i)
    return list(divisors)

