# Finding multiplicative inverses in Finite Field Z_p (where p is prime) in Python 3.13+
def field_inverse(a, p):
    # Using Extended Euclidean Algorithm or brute force for Z_p
    for x in range(1, p):
        if (a * x) % p == 1:
            return x
    return None

p = 7  # Prime modulus creates a finite field F_7
