def verify_field_inverses(p):
    for a in range(1, p):
        found = False
        for x in range(1, p):
            if (a * x) % p == 1:
                found = True
                break
        if not found:
            return False
    return True

def field_div(a, b, p):
    # computes (a / b) mod p in finite field F_p
    b_inv = None
    for x in range(1, p):
        if (b * x) % p == 1:
            b_inv = x
            break
    return (a * b_inv) % p

