# Handling Directed vs Undirected Graph Degrees in Python 3.13+
class DiGraph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.adj = {v: [] for v in vertices}

    def add_edge(self, u, v):
        self.adj[u].append(v)  # Directed: u -> v only

    def compute_degrees(self):
        in_degree = {v: 0 for v in self.vertices}
        out_degree = {v: len(self.adj[v]) for v in self.vertices}

        for u in self.adj:
            for v in self.adj[u]:
                in_degree[v] += 1

        return in_degree, out_degree

