from collections import deque

# Function to check if a graph is bipartite using BFS (Python 3.13+)
def is_bipartite(n, adj):
    color = [-1] * n  # -1: uncolored, 0: set 1, 1: set 2

    for i in range(n):
        if color[i] == -1:
            queue = deque([i])
            color[i] = 0

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]  # Alternate color
                        queue.append(v)
                    elif color[v] == color[u]:
                        return False  # Adjacent vertices have the same color
    return True

# Example usage:
# Graph with 4 vertices forming a 4-cycle (bipartite)
