def greedy_colouring(adjacency_list):
    colour = {}
    for node in adjacency_list:
        # Find colours of already-coloured neighbours
        neighbour_colours = {colour[n] for n in adjacency_list[node] if n in colour}

        # Assign the first available colour
        c = 0
        while c in neighbour_colours:
            c += 1
        colour[node] = c
    return colour

